<script setup lang="ts">
import { formatAmount } from '../../shared/formatAmount';

import {computed,inject,onMounted,ref,watch} from 'vue';
import {adminSessionKey} from './adminSession';
import {ApiError,refreshSession,accessAdminListGetApiV1AdminAccessKeys,accessAdminSecretGetApiV1AdminAccessKeysIdSecret,accessStatusPatchApiV1AdminAccessKeysIdStatus,paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions,paymentAdminAccountPatchApiV1AdminPaymentsAccountsId,billingBalanceGetApiV1BillingWalletsKeyId,billingEntriesGetApiV1BillingWalletsKeyIdLedger,billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments} from './api';
import AmountAdjustment from './AmountAdjustment.vue';
const props=withDefaults(defineProps<{userId:string;initialType?:'PERSONAL'|'ENTERPRISE'|'API';initialCreateKey?:boolean;showLedger?:boolean;typeOnly?:boolean}>(),{initialType:'PERSONAL',initialCreateKey:false,showLedger:true});
const emit=defineEmits<{changed:[accountType?:string];cancel:[]}>();
const session=inject(adminSessionKey);const primary=computed(()=>session?.currentAdmin.value?.role==='ADMIN'&&session.currentAdmin.value.primary===true);
type Key=Awaited<ReturnType<typeof accessAdminListGetApiV1AdminAccessKeys>>['data'][number];
type Options=Awaited<ReturnType<typeof paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions>>['data'];
type AccountBody=Parameters<typeof paymentAdminAccountPatchApiV1AdminPaymentsAccountsId>[1];
const keyLoaded=ref(false),ledgerLoaded=ref(false);
const options=ref<Options|null>(null),key=ref<Key|null>(null),type=ref(props.initialType),createKey=ref(props.initialCreateKey||props.initialType==='API'),secret=ref(''),balance=ref('—'),error=ref(''),notice=ref(''),busy=ref(false),pendingAmount=ref(false),attempt=ref<AccountBody|null>(null);
const ledger=ref<Awaited<ReturnType<typeof billingEntriesGetApiV1BillingWalletsKeyIdLedger>>['data']>([]),audit=ref<Awaited<ReturnType<typeof billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments>>['data']>([]);
let storageKey='';const names:Record<string,string>={PERSONAL:'个人',ENTERPRISE:'企业',API:'API'};
const readOnly=computed(()=>!primary.value&&(options.value?.accountType==='API'||options.value?.accountType==='ENTERPRISE'));
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(cause){error.value=cause instanceof ApiError&&cause.status===403?'当前管理员没有此操作权限。':props.typeOnly?'用户类型保存失败，请重试。':'操作失败，用户已保存；请保留当前输入并重试。';}finally{busy.value=false;}}
watch(type,value=>{if(value==='API')createKey.value=true;});
function remember(value:AccountBody|null){attempt.value=value;try{if(storageKey){if(value)sessionStorage.setItem(storageKey,JSON.stringify(value));else sessionStorage.removeItem(storageKey);}}catch{/* The same request remains available in memory. */}}
async function load(){const [account,keys]=await Promise.all([paymentAdminOptionsGetApiV1AdminPaymentsRechargeOptions({userId:props.userId}),props.typeOnly?Promise.resolve({data:[]}):accessAdminListGetApiV1AdminAccessKeys({ownerId:props.userId})]);options.value=account.data;if(!attempt.value&&account.data.accountType==='API')type.value='API' as typeof type.value;keyLoaded.value=true;key.value=keys.data.find(item=>item.ownerId===props.userId)||null;if(!attempt.value&&(account.data.accountType==='PERSONAL'||account.data.accountType==='ENTERPRISE'))type.value=account.data.accountType;if(key.value?.keyId){const [wallet,entries,adjustments]=await Promise.all([billingBalanceGetApiV1BillingWalletsKeyId(key.value.keyId),billingEntriesGetApiV1BillingWalletsKeyIdLedger(key.value.keyId),billingAdjustmentsGetApiV1AdminBillingWalletsKeyIdAdjustments(key.value.keyId)]);ledgerLoaded.value=true;balance.value=wallet.data.availablePoints4||'读取失败';ledger.value=entries.data;audit.value=adjustments.data;}else{ledgerLoaded.value=true;balance.value='—';ledger.value=[];audit.value=[];}}
async function save(){if((!attempt.value&&(!options.value||readOnly.value))||pendingAmount.value)return;await run(async()=>{const retry=!!attempt.value;const body=attempt.value||{requestId:crypto.randomUUID(),accountType:type.value,createKey:(!props.typeOnly&&createKey.value)||type.value==='API'};remember(body);try{await paymentAdminAccountPatchApiV1AdminPaymentsAccountsId(props.userId,body);}catch(cause){if(cause instanceof ApiError&&([400,422].includes(cause.status)||(!retry&&[403,409].includes(cause.status))))remember(null);throw cause;}remember(null);if(props.typeOnly){emit('changed',body.accountType);return;}notice.value='账户已保存。';await load();emit('changed');});}
async function reveal(){if(!key.value?.keyId||!primary.value)return;await run(async()=>{secret.value=(await accessAdminSecretGetApiV1AdminAccessKeysIdSecret(key.value!.keyId!)).data.secret||'';});}
async function copy(){await run(async()=>{await navigator.clipboard.writeText(secret.value);notice.value='Key 已复制。';});}
async function toggle(){if(!key.value?.keyId)return;await run(async()=>{await accessStatusPatchApiV1AdminAccessKeysIdStatus(key.value!.keyId!,{enabled:!key.value!.enabled});secret.value='';await load();emit('changed');});}
async function changed(){await run(load);emit('changed');}
onMounted(()=>void run(async()=>{const auth=await refreshSession();storageKey=auth.authenticated&&auth.user?.id?`xzwl-user-account:${auth.user.id}:${props.userId}`:'';try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(saved&&typeof saved.requestId==='string'&&['PERSONAL','ENTERPRISE','API'].includes(saved.accountType)&&typeof saved.createKey==='boolean'){attempt.value=saved;type.value=saved.accountType;createKey.value=saved.createKey;}}catch{/* Malformed drafts do not authorize requests. */}await load();}));
defineExpose({busy});
</script>
<template>
 <div class="user-account" :class="{'type-only-account':typeOnly}"><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <section class="account-section"><header v-if="!typeOnly"><h2>账户与本人主 Key</h2><button type="button" class="secondary-action" :disabled="busy" @click="run(load)">刷新账户</button></header>
 <p v-if="!options&&!attempt">正在读取真实账户…</p>
 <template v-else><p v-if="!typeOnly">当前账户：{{names[options?.accountType||'']||'尚未设置'}} · 用户 ID：{{userId}}</p>
 <form @submit.prevent="save"><label>{{typeOnly?'用户类型':'账户类型'}}<select :aria-label="typeOnly?'用户类型':'账户类型'" v-model="type" :disabled="busy||readOnly||!!attempt||pendingAmount"><option v-if="options?.accountType==='API'||attempt?.accountType==='API'||(primary&&(typeOnly||!options?.accountType))" value="API">API</option><option value="PERSONAL">个人</option><option v-if="primary||options?.accountType==='ENTERPRISE'||attempt?.accountType==='ENTERPRISE'" value="ENTERPRISE">企业</option></select></label>
 <p v-if="readOnly">{{options?.accountType==='API'?'API 账户仅主管理员可以修改。':'企业账户仅主管理员可以修改。'}}</p>
 <label v-if="!typeOnly&&!key" class="checkbox-label"><input v-model="createKey" type="checkbox" :disabled="busy||readOnly||!!attempt||pendingAmount||type==='API'"/>由服务端安全生成本人主 Key</label>
 <p v-if="attempt" role="status">账户保存响应尚未确认，将使用原请求重试。</p>
 <button v-if="typeOnly" type="button" :disabled="busy" @click="emit('cancel')">取消</button>
 <button v-if="!readOnly||attempt" class="primary-action" :disabled="busy||!!pendingAmount">{{typeOnly?(busy?'保存中…':attempt?'重试':'确定'):attempt?'重试原账户保存':'保存账户'+(createKey&&!key?'并生成 Key':'')}}</button></form>
 <template v-if="!typeOnly"><p v-if="!key" class="key-empty">{{keyLoaded?'未生成 Key':'Key 尚未读取'}}</p><div v-else class="key-controls"><p>主 Key：{{key.enabled?'已启用':'已停用'}}</p>
 <div class="account-actions"><button v-if="primary" type="button" class="secondary-action" :disabled="busy" @click="secret?secret='':reveal()">{{secret?'隐藏 Key':'查看 Key'}}</button><button v-if="secret" type="button" class="secondary-action" :disabled="busy" @click="copy">复制 Key</button><button type="button" class="secondary-action" :disabled="busy" @click="toggle">{{key.enabled?'停用 Key':'启用 Key'}}</button></div><p v-if="secret" class="key-secret"><code>{{secret}}</code></p><p v-if="!primary">Key 密文仅主管理员可以查看。</p></div>
 <p>可用余额：<strong>{{ formatAmount(balance) }}</strong> 积分</p></template></template></section>
 <AmountAdjustment v-if="!typeOnly" :user-id="userId" :key-id="key?.keyId||undefined" :options="busy||attempt?null:options" @changed="changed" @pending="pendingAmount=$event"/>
 <section v-if="!typeOnly&&showLedger" class="account-section" aria-label="真实余额流水"><header><h2>余额流水</h2></header><p v-if="!ledger.length">{{ledgerLoaded?'暂无流水':'流水尚未读取'}}</p><div v-else class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>积分</th><th>余额</th><th>请求号</th></tr></thead><tbody><tr v-for="item in ledger" :key="item.requestId||undefined"><td>{{item.recordedAt}}</td><td>{{item.kind}}</td><td>{{ formatAmount(item.points4) }}</td><td>{{ formatAmount(item.balanceAfter4) }}</td><td>{{item.requestId}}</td></tr></tbody></table></div></section>
 <section v-if="!typeOnly&&showLedger" class="account-section" aria-label="扣减审计"><h2>扣减审计</h2><p v-if="!audit.length">{{ledgerLoaded?'暂无扣减记录':'扣减记录尚未读取'}}</p><div v-else class="table-wrap"><table><thead><tr><th>时间</th><th>人民币（元）</th><th>兑换比例</th><th>积分</th><th>操作者</th><th>备注</th></tr></thead><tbody><tr v-for="item in audit" :key="item.requestId||undefined"><td>{{item.recordedAt}}</td><td>{{ formatAmount(item.amount4) }}</td><td>{{ formatAmount(item.rateSnapshot4) }}</td><td>{{ formatAmount(item.points4) }}</td><td>{{item.operatorId}}</td><td>{{item.remark}}</td></tr></tbody></table></div></section>
 </div>
</template>
<style scoped>
.user-account{display:grid;gap:24px;min-width:0}.account-section{display:grid;gap:14px;padding-top:20px;border-top:1px solid #2b3232;min-width:0}.account-section header{display:flex;gap:12px;align-items:center;justify-content:space-between}.user-account h2,.user-account p{margin:0}.user-account h2{font-size:17px}.user-account p{color:#a9b7b7;line-height:1.6;font-size:13px;overflow-wrap:anywhere}.user-account [role=alert]{color:#ffb7a2}.user-account form,.user-account label{display:grid;gap:12px}.user-account select{width:100%;min-height:44px;padding:10px;border:1px solid #3a4646;border-radius:8px;color:#eef3f3;background:#0d1111}.user-account .checkbox-label{display:flex;align-items:center}.checkbox-label input{width:20px;height:20px}.key-controls{display:grid;gap:12px}.account-actions{display:flex;gap:8px;flex-wrap:wrap}.key-secret{padding:12px;background:#090c0c;border:1px solid #3a4646;border-radius:8px}.user-account button:disabled{opacity:.45;cursor:not-allowed}.user-account table{min-width:600px}
</style>
